export function initPage(){
(() => {
 const langs=['en','fr','es','de'],locale=langs.includes(document.documentElement.lang)?document.documentElement.lang:'en';
 const path=location.pathname.replace(/^\/(fr|es|de)(?=\/)/,'')||'/';
 document.querySelectorAll('[data-site-language]').forEach(a=>{const target=a.dataset.siteLanguage;a.href=(target==='en'?'':'/'+target)+path+location.search+location.hash;a.addEventListener('click',()=>{a.href=(target==='en'?'':'/'+target)+(location.pathname.replace(/^\/(fr|es|de)(?=\/)/,'')||'/')+location.search+location.hash;try{localStorage.setItem('mt-elk-site-language',target)}catch{}});});
 // Use explicit choices; URLs identify each edition and preserve normal Back behavior.
 function localLink(a){if(a.dataset.siteLanguage||locale==='en')return;const raw=a.getAttribute('href');if(!raw||!raw.startsWith('/')||raw.startsWith('//')||/^\/(fr|es|de)\//.test(raw))return;const u=new URL(raw,location.origin);if(/\.[a-z0-9]+$/i.test(u.pathname)||/^\/(assets|records|vendor|api)\//.test(u.pathname))return;a.setAttribute('href','/'+locale+u.pathname+u.search+u.hash);}
 const memory=window.MTSiteLanguageMemory ||= {texts:new WeakMap(),attrs:new WeakMap()};
 const templates={de:{lesson:'Lektion verfügbar',lessons:'Lektionen verfügbar',record:'Dokument verfügbar',records:'Dokumente verfügbar',saved:'gespeicherte Ressourcen'},en:{lesson:'lesson available',lessons:'lessons available',record:'record available',records:'records available',saved:'saved resources'},fr:{lesson:'leçon disponible',lessons:'leçons disponibles',record:'document disponible',records:'documents disponibles',saved:'ressources enregistrées'},es:{lesson:'lección disponible',lessons:'lecciones disponibles',record:'documento disponible',records:'documentos disponibles',saved:'recursos guardados'}}[locale];
 (locale==='en'?Promise.resolve({}):fetch('/assets/translations-'+locale+'.json').then(r=>{if(!r.ok)throw Error('Translation unavailable');return r.json()})).then((window.MTPageRouter?.bindPage||((fn)=>fn))(dict=>{
  function wording(t){if(locale==='en')return t;if(dict[t])return dict[t];if(locale==='de'){let found=t.match(/^(\d+) matching resources\. Showing (\d+)\.$/);if(found)return found[1]+' passende Ressourcen. '+found[2]+' angezeigt.';found=t.match(/^(\d+) saved resources?\.$/);if(found)return found[1]+(found[1]==='1'?' gespeicherte Ressource.':' gespeicherte Ressourcen.');found=t.match(/^Remove (.+) from field guide$/);if(found)return found[1]+' aus dem Feldführer entfernen';}let loop=t.match(/^Loop track: (on|off)$/);if(loop&&locale==='de')return 'Titel wiederholen: '+(loop[1]==='on'?'an':'aus');if(loop)return (locale==='fr'?'Lecture en boucle : ':'Repetición : ')+(locale==='fr'?(loop[1]==='on'?'activée':'désactivée'):(loop[1]==='on'?'activada':'desactivada'));let removal=t.match(/^Remove (q|call|species|topic) filter: (.+)$/);if(removal&&locale==='de')return 'Filter entfernen: '+({q:'Suche',call:'Modell',species:'Tierart',topic:'Thema'}[removal[1]])+' – '+removal[2];if(removal)return (locale==='fr'?'Supprimer le filtre ':'Quitar filtro ')+({fr:{q:'recherche',call:'modèle',species:'espèce',topic:'sujet'},es:{q:'búsqueda',call:'modelo',species:'especie',topic:'tema'}}[locale][removal[1]])+' : '+removal[2];let m=t.match(/^(\d+) (lessons?|records?) available$/);if(m)return m[1]+' '+templates[m[2]];m=t.match(/^(\d+) saved resources?$/);if(m)return m[1]+' '+templates.saved;return t;}
  function scan(node){if(node.nodeType===3){if(!node.parentElement||node.parentElement.closest('script,style,[data-site-language],[data-live-store],[data-policy-source],.ec-size,.ec-store,input,textarea'))return;const current=node.nodeValue.trim();if(!memory.texts.has(node))memory.texts.set(node,current);const original=memory.texts.get(node),v=wording(original);if(current&&v!==current)node.nodeValue=node.nodeValue.replace(current,v);return;}if(node.nodeType!==1&&node.nodeType!==9)return;if(node.nodeType===1){if(node.matches('script,style'))return;if(node.matches('a[href]'))localLink(node);for(const k of ['aria-label','title','placeholder']){const v=node.getAttribute(k);if(v){let values=memory.attrs.get(node);if(!values){values={};memory.attrs.set(node,values)}values[k]??=v;const translated=wording(values[k]);if(translated!==v)node.setAttribute(k,translated);}}}for(const child of [...node.childNodes])scan(child);}
  // English pages are already emitted in English. Restore only persistent controls from prior locales.
  if(locale==='en'){document.querySelectorAll('body > [data-site-persist]').forEach(scan);return;}
  scan(document.body);new MutationObserver(changes=>{for(const m of changes){if(m.type==='characterData')scan(m.target);else if(m.type==='attributes')scan(m.target);else for(const n of m.addedNodes)scan(n);}}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['href','aria-label','title','placeholder']});
 })).catch(()=>{/* Static translated pages and language links remain usable. */});
})();

}
if(!window.MTPageRouter?.booting){if(window.MTPageRouter)window.MTPageRouter.run(initPage);else initPage();}
